package backend

import "errors"

type Item struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

type Response struct {
	Items     []Item `json:"items"`
	NextCursor *string `json:"next_cursor"`
}

type PageFetcher func(cursor *string, limit int) (Response, error)

var items = []Item{
	{ID: "i1", Name: "one"},
	{ID: "i2", Name: "two"},
	{ID: "i3", Name: "three"},
}

func GetItems(cursor *string, limit int) (Response, error) {
	if limit < 1 {
		return Response{}, errors.New("limit must be at least 1")
	}
	start := 0
	if cursor != nil {
		if *cursor != "cursor-2" {
			return Response{}, errors.New("invalid cursor")
		}
		start = 2
	}
	if start >= len(items) {
		return Response{Items: []Item{}, NextCursor: nil}, nil
	}
	end := start + limit
	if end > len(items) {
		end = len(items)
	}
	page := Response{Items: items[start:end]}
	if end < len(items) {
		next := "cursor-2"
		page.NextCursor = &next
	}
	return page, nil
}

func FetchAll(fetch PageFetcher, limit int) ([]Item, error) {
	if fetch == nil {
		return nil, errors.New("fetcher is required")
	}
	if limit < 1 {
		return nil, errors.New("limit must be at least 1")
	}
	var all []Item
	var cursor *string
	for {
		page, err := fetch(cursor, limit)
		if err != nil {
			return nil, err
		}
		all = append(all, page.Items...)
		if page.NextCursor == nil {
			return all, nil
		}
		next := *page.NextCursor
		cursor = &next
	}
}

// FetchItems exercises the endpoint and returns all items across pages.
func FetchItems() ([]Item, error) {
	return FetchAll(GetItems, 2)
}

